        "row_key": "苍蝇",
        "lyric_excerpt": "收集这世界的背面的残渣。啦啦啦，以肮脏的名义把世界净化。人类缺乏情趣，把决斗幸存当胜利，胜利当作正义，把正义当上帝。过度攫取，占有欲，去掠夺然后再舍弃，制造垃圾。它带着荣耀死去，灵魂到天堂或地狱，但我哪也不去，我留在这儿唱唱歌。",
